head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/list_common_etn.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
// 세션정보를 얻기위한 함수사용
//★Wcraft guide★ include부분 주석처리 -> include("../js/buttonSet.js");

//#include("../js/pre_newlisting.js");

scwin.vScrenID = "ULDSTF08025.xml";
scwin.vScrenTpCD = "";
scwin.fn_GetPar, scwin.fn_SetPar;
scwin.vBzProcsNo = "";
scwin.vIsurCd = ""; //발행회사코드
scwin.vIsuCd = ""; //종목코드
scwin.vIsuNm = ""; //종목명
scwin.vIsuAbbrv = ""; //종목약명
scwin.vAcptNo = ""; //접수번호

scwin.v_SaveKind = "";
scwin.TR_JOB;
scwin.VListBzTpCd = LIST_BZ_TP_CD_709; //종목명변경
scwin.vSYMBL_INPUT_CD;
scwin.vSecuGrpId;
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명 : fn_select_read_init()
 * 설명    : 종목명변경 상장내역 조회
 ***********************************************/
scwin.fn_select_read_init = function() {
    var url = "";
    var srvMethod = "selectIsuNmChgApplDetail";
    url = "/etn/EtnChgList.do?method=" + srvMethod;
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ACPT_NO=" + scwin.vAcptNo;
    dts_Isu.DataID = encodeURI(url);
    dts_Isu.Reset();

    //발행기관코드 (parent에서 얻어올 수도 있음.
    //저장시 필요함.
    scwin.vIsurCd = dts_Isu.getCellData(1, "ISUR_CD");
    scwin.vIsuNm = dts_Isu.getCellData(1, "ISU_NM");
    scwin.vIsuAbbrv = dts_Isu.getCellData(1, "ISU_ABBRV");
};


/********************************************** 
 * 함수명 : fn_CheckForm()
 * 설명    : Form Validation Check
 ***********************************************/
scwin.fn_CheckForm = function() {
    var vCurDate = $c.ut.cGetToday("yyyymmdd");
    if (scwin.vIsuCd == "") {
        $c.win.alert("[종목]이 조회되어 있지 않습니다.");
        return false;
    }
    if ($c.stf.getObjectValue(edt_CHG_LIST_DD) == "") {
        $c.win.alert("[변경상장일]을 입력하세요.");
        edt_CHG_LIST_DD.focus();
        return false;
    }

    //병합비율, 분할비율 둘다 값이 없을때는 종목명 변경으로 인식
    //Check Max Length
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_NM) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_NM))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_NM, 80, "한글종목명")) return false;
        }
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ABBRV1, 40, "한글종목약명")) return false;
        }
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_NM, 80, "영문종목명")) return false;
        }
    }
    if ($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1) != "") {
        if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1))) > 1) {
            if (!$c.stf.checkMaxLength(txb_AFCHG_ISU_ENG_ABBRV1, 40, "영문종목약명")) return false;
        }
    }
    return true;
};


/********************************************** 
 * 함수명 : fn_SetFormField()
 * 설명    : 신규저장,수정하기 전 Form Field Value에 대하여 2바이트 체크 
 *             현업의 미입력에서도 '-' 하이픈을 입력하는 경우가 많아 처리함
 ***********************************************/
scwin.fn_SetFormField = function() {
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_NM))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_NM, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ABBRV1))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_ABBRV1, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_NM))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_ENG_NM, "");
    }
    if (eval($c.stf.getStringSize($c.stf.getObjectValue(txb_AFCHG_ISU_ENG_ABBRV1))) == 1) {
        $c.stf.setObjectValue(txb_AFCHG_ISU_ENG_ABBRV1, "");
    }
};



/********************************************** 
 * 함수명 : fn_save()
 * 설명    : 종목명 변경상장 내역 > 신규저장
 ***********************************************/
scwin.fn_save = function() {
    scwin.TR_JOB = 'I';
    if ($c.en.fn_CheckForm() && scwin.fn_dupCheck()) {
        //Transaction 처리전 안내문구
        if (!$c.lce.fn_isProcess(scwin.TR_JOB)) return;
        if (scwin.vBzProcsNo == undefined || scwin.vBzProcsNo == "") {
            scwin.vBzProcsNo = $c.stf.fn_getNewBzProcNo(dts_BzProcsNo);
        }
        if (scwin.vBzProcsNo.length != 14) {
            $c.win.alert($c.stf.getMessageParam("MSG-0010", ""));
        } else {
            scwin.fn_trs(TRS_IDX_INSERT);
        }
    }
};




/********************************************** 
 * 함수명 : fn_trs(trxIdx)
 * 설명    : 트랜잭션 처리 구분(저장,수정,삭제)
 ***********************************************/
scwin.fn_trs = function(trsIdx) {
    var srvMethod = "";
    var trsKind;
    if (scwin.TR_JOB == 'I') {
        //Form 설정
        scwin.fn_SetFormField();
        scwin.vScrenTpCD = SCREN_PROCS_TP_CD_02;
        srvMethod = "insertIsuNmApplDtl";
        trsKind = TR_JOB_INSERT;
        trs_Save.Action = $c.lce.fn_encodeNSession("/etn/EtnChgList.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + scwin.vScrenTpCD + "&method=" + srvMethod);
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInput=dts_Isu)";
        trs_Save.Parameters = "TRS_IDX=" + trsKind + ",LIST_BZ_TP_CD=" + scwin.VListBzTpCd + ",LD_MKT_TP_CD=1" + ",TRANSTR_EMP_NO=" + js_emp_no + ",BZ_PROCS_NO=" + scwin.vBzProcsNo + ",ISUR_CD=" + scwin.vIsurCd + ",ISU_CD=" + scwin.vIsuCd + ",ACPT_NO=" + scwin.vAcptNo;
        trs_Save.Post();
    }
};



/********************************************** 
 * 함수명 : fn_parentRefresh()
 * 설명    : Parent 화면 Refresh()
 ***********************************************/
scwin.fn_parentRefresh = function() {
    //Parent 신청내역 화면 Refresh
    var parentWin = $c.frame.path("../");
    parentWin.txb_SearchIsuCd2.setValue(scwin.vIsuCd);
    parentWin.txb_SearchIsuNm2.setValue(scwin.vIsuAbbrv);
    $c.stf.setObjectValue(parentWin.cmb_ISUR_CD2, scwin.vIsurCd);
    parentWin.fn_list_chglist_appl(scwin.vIsurCd, scwin.vIsuCd);
    parentWin.fn_list_chglist_sync();
};


/********************************************** 
 * 함수명 : fn_dupCheck()
 * 설명    : 종목 중복날짜 체크
 ***********************************************/
scwin.fn_dupCheck = function() {
    var chgDd = $c.stf.getObjectValue(edt_CHG_LIST_DD);
    var isNotDup = true;
    url = "/etn/EtnChgList.do?method=selectIsuNmChgDupList";
    url += "&SCREN_ID=" + scwin.vScrenID;
    url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;
    url += "&ISU_CD=" + scwin.vIsuCd + "&CHG_DD=" + chgDd;
    dts_DupChk.DataID = encodeURI(url);
    dts_DupChk.reset();
    if (dts_DupChk.getTotalRow() > 0) {
        isNotDup = false;
        $c.win.alert("동일한 날짜에 변경상장 지정된 종목이 존재합니다.");
    }
    return isNotDup;
};
scwin.btn_Close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.dts_Isu_OnLoadError = function() {
    $c.stf.alert_error(dts_Isu);
};
scwin.dts_Isu_OnLoadCompleted = function(rowcount) {

};
scwin.trs_Save_OnFail = function() {
    $c.lce.fn_alertMsg('F');
};
scwin.trs_Save_OnSuccess = async function() {
    $c.lce.fn_alertMsg('S');

    //Refresh Parent Frame
    scwin.fn_parentRefresh();

    //닫기
    await $c.frame.CloseFrame();
};
scwin.gform_onload = function() {
    var parentWin = $c.frame.path("../");
    scwin.vSecuGrpId = parentWin.fr_SecuGrpId;

    //
    $c.libRoundPanel.PanelToGroupBox(panel_Item);

    /* buttonSet의 초기화를 수행한다.  각 용도에 맞게 이미지ID와 onclick event시 수행할 function을 지정한다. */
    buttonSet.setSaveInfo(btn_Save, fn_save); // 저장

    /*	
    if (vSecuGrpId == SECUGRP_ID_EN) {
    	txb_memo.disabled = false;
    	txb_memo.value = "(미입력시 '변경전' 값이 저장됩니다.)";
    } else {
    	txb_memo.disabled = true;
    }
    */

    //Parent Data
    scwin.v_SaveKind = parentWin.vIsuNmChgApplKind; //Transaction 구분: 신규(N), 수정(U)
    //v_UpdParam = parentWin.v_UpdItmIsurParam;	//변경상장내역 Param

    if (scwin.v_SaveKind == "N") {
        scwin.vBzProcsNo = ""; //업무처리번호
        scwin.vIsuCd = parentWin.clickIsuCd; //종목코드   getObjectValue(parentWin.txb_SearchIsuCd2);
        scwin.vAcptNo = parentWin.clickAcptNo; //접수번호

    }

    //데이터 조회
    scwin.fn_select_read_init();
};
scwin.img_CHG_LIST_DD_onclick = function() {
    //변경상장일 달력클릭
    popUpCalendar2(edt_CHG_LIST_DD);
};
